// Pick the highest-relevance article from the last 4h, score >= 7
// ES5/ASCII only
var SCORE_MIN = 7;
var LOOKBACK_MS = 4 * 3600 * 1000;

var newsItem = $input.item.json;
var articles = (newsItem && newsItem.articles) ? newsItem.articles : [];
if (!articles.length) {
  return [{ json: { shouldTweet: false, reason: 'no_articles' } }];
}

var cutoff = new Date(Date.now() - LOOKBACK_MS);
var candidates = [];
for (var i = 0; i < articles.length; i++) {
  var a = articles[i];
  if ((a.relevance_score || 0) < SCORE_MIN) continue;
  var pub = new Date((a.published_at || '').replace('Z', '+00:00'));
  if (isNaN(pub.getTime()) || pub < cutoff) continue;
  candidates.push(a);
}

if (!candidates.length) {
  return [{ json: { shouldTweet: false, reason: 'no_high_score_recent_articles', total: articles.length } }];
}

// Sort by relevance desc, pick top
candidates.sort(function(x, y) { return (y.relevance_score || 0) - (x.relevance_score || 0); });
var best = candidates[0];

// Format sentiment emoji
var EMOJI = { bullish: '\uD83D\uDCC8', bearish: '\uD83D\uDCC9', neutral: '\u26AA' };
var emoji = EMOJI[best.sentiment] || EMOJI.neutral;

// Format assets tag string
var assetTags = '';
if (best.assets && best.assets.length) {
  assetTags = ' ' + best.assets.slice(0, 3).map(function(a) { return '$' + a; }).join(' ');
}

// Truncate title to 80 chars
var title = (best.title || '').substring(0, 80);
if ((best.title || '').length > 80) title += '...';

// Truncate summary to 100 chars for tweet
var summary = (best.summary || '').substring(0, 100);
if ((best.summary || '').length > 100) summary += '...';

// Build tweet (max 280 chars)
var url = best.url || '';
var base = emoji + ' ' + title + '\n\n' + summary + '\n\n' + url + assetTags + ' #crypto #AlphaForgeAI';

// Safety trim to 280
if (base.length > 280) {
  var excess = base.length - 280;
  summary = summary.substring(0, Math.max(0, summary.length - excess - 3)) + '...';
  base = emoji + ' ' + title + '\n\n' + summary + '\n\n' + url + assetTags + ' #crypto #AlphaForgeAI';
}

return [{ json: { shouldTweet: true, tweet: base, article: best } }];
